ALTER TABLE public.notas_fiscais ADD COLUMN itens_xml jsonb NOT NULL DEFAULT '[]';
ALTER TABLE public.ocorrencias ADD COLUMN item_numero text, ADD COLUMN produto_codigo text, ADD COLUMN produto_descricao text, ADD COLUMN quantidade_item numeric, ADD COLUMN anexos_paths text[] NOT NULL DEFAULT '{}';
CREATE TABLE public.configuracao_descarga (chave text PRIMARY KEY DEFAULT 'padrao' CHECK(chave='padrao'), favorecido text NOT NULL DEFAULT 'COELHO E SILVA LTDA', pix text NOT NULL DEFAULT '38.974.133/0001-31', tipo_chave text NOT NULL DEFAULT 'CNPJ');
GRANT SELECT,INSERT,UPDATE ON public.configuracao_descarga TO authenticated; GRANT ALL ON public.configuracao_descarga TO service_role;
ALTER TABLE public.configuracao_descarga ENABLE ROW LEVEL SECURITY;
CREATE POLICY payment_read ON public.configuracao_descarga FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY payment_admin ON public.configuracao_descarga FOR ALL TO authenticated USING(private.has_role(auth.uid(),'administrador')) WITH CHECK(private.has_role(auth.uid(),'administrador'));
CREATE FUNCTION public.tg_guard_xml_items() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ DECLARE i jsonb; BEGIN IF TG_OP='UPDATE' AND NEW.itens_xml IS NOT DISTINCT FROM OLD.itens_xml THEN RETURN NEW; END IF; IF TG_OP='UPDATE' AND OLD.itens_xml<>'[]'::jsonb THEN RAISE EXCEPTION 'Produtos fiscais já preservados'; END IF; IF jsonb_typeof(NEW.itens_xml)<>'array' THEN RAISE EXCEPTION 'Produtos inválidos'; END IF; FOR i IN SELECT value FROM jsonb_array_elements(NEW.itens_xml) LOOP IF coalesce(i->>'numero','')='' OR coalesce(i->>'codigo','')='' OR coalesce(i->>'descricao','')='' OR (i->>'quantidade')::numeric IS NULL OR (i->>'quantidade')::numeric<0 THEN RAISE EXCEPTION 'Item XML inválido'; END IF; END LOOP; IF (SELECT count(*) FROM jsonb_array_elements(NEW.itens_xml))<>(SELECT count(DISTINCT value->>'numero') FROM jsonb_array_elements(NEW.itens_xml)) THEN RAISE EXCEPTION 'Número de item duplicado'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_xml_items BEFORE INSERT OR UPDATE ON public.notas_fiscais FOR EACH ROW EXECUTE FUNCTION public.tg_guard_xml_items();
CREATE FUNCTION public.recuperar_itens_xml(_nota uuid,_chave text,_itens jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT private.can_write(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; UPDATE public.notas_fiscais SET itens_xml=_itens WHERE id=_nota AND chave_nfe=_chave AND itens_xml='[]'::jsonb; IF NOT FOUND THEN RAISE EXCEPTION 'XML não corresponde à nota ou os produtos já existem'; END IF; INSERT INTO public.historico(entidade,entidade_id,acao,descricao,user_id) VALUES('nota',_nota,'produtos_xml','Produtos recuperados do XML original',auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.recuperar_itens_xml(uuid,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.recuperar_itens_xml(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.tg_occurrence_item() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE n public.notas_fiscais;i jsonb; BEGIN IF TG_OP='UPDATE' THEN IF NEW.item_numero IS DISTINCT FROM OLD.item_numero OR NEW.produto_codigo IS DISTINCT FROM OLD.produto_codigo OR NEW.produto_descricao IS DISTINCT FROM OLD.produto_descricao OR NEW.quantidade_item IS DISTINCT FROM OLD.quantidade_item OR NEW.carga_entrada_id IS DISTINCT FROM OLD.carga_entrada_id THEN RAISE EXCEPTION 'Identidade da ocorrência preservada'; END IF; RETURN NEW; END IF; SELECT * INTO n FROM public.notas_fiscais WHERE id=NEW.nota_id FOR UPDATE; IF NEW.item_numero IS NOT NULL THEN SELECT value INTO i FROM jsonb_array_elements(n.itens_xml) WHERE value->>'numero'=NEW.item_numero; IF i IS NULL THEN RAISE EXCEPTION 'Produto não pertence à nota fiscal'; END IF; IF NEW.quantidade IS NULL OR NEW.quantidade<=0 THEN RAISE EXCEPTION 'Informe quantidade afetada positiva'; END IF; NEW.produto_codigo:=i->>'codigo'; NEW.produto_descricao:=i->>'descricao'; NEW.quantidade_item:=(i->>'quantidade')::numeric; NEW.unidade:=i->>'unidade'; END IF; NEW.carga_entrada_id:=n.carga_entrada_id; NEW.chave_nfe:=n.chave_nfe; RETURN NEW; END $$;
CREATE TRIGGER a_occurrence_item BEFORE INSERT OR UPDATE ON public.ocorrencias FOR EACH ROW EXECUTE FUNCTION public.tg_occurrence_item();
CREATE FUNCTION public.calcular_descarga(_linhas jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ DECLARE l jsonb;q numeric;t numeric;s numeric;total numeric:=0;seen text[]:='{}';result jsonb:='[]'; BEGIN IF jsonb_typeof(_linhas)<>'array' OR jsonb_array_length(_linhas)=0 THEN RAISE EXCEPTION 'Selecione uma modalidade'; END IF; FOR l IN SELECT value FROM jsonb_array_elements(_linhas) LOOP IF l->>'modalidade' NOT IN ('peso','volume','pallet') OR l->>'modalidade'=ANY(seen) THEN RAISE EXCEPTION 'Modalidade inválida ou repetida'; END IF; seen:=array_append(seen,l->>'modalidade');q:=(l->>'quantidade')::numeric;t:=(l->>'tarifa')::numeric; IF q IS NULL OR t IS NULL OR q<0 OR t<0 OR q::text IN ('NaN','Infinity','-Infinity') OR t::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Quantidade e tarifa inválidas'; END IF; s:=round(q*t/CASE WHEN l->>'modalidade'='peso' THEN 1000 ELSE 1 END,2);total:=total+s;result:=result||jsonb_build_array(l||jsonb_build_object('subtotal',s)); END LOOP; RETURN jsonb_build_object('cobrancas',result,'valor_total',total); END $$;
CREATE OR REPLACE FUNCTION public.tg_recebimento_documento_identidade() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE nome text;kg numeric;tarifa numeric; BEGIN IF auth.uid() IS NULL OR NOT private.can_receive(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão para salvar documentos'; END IF; SELECT coalesce(nullif(p.nome,''),p.email) INTO nome FROM public.profiles p WHERE p.id=auth.uid(); PERFORM 1 FROM public.cargas_entrada WHERE id=NEW.carga_entrada_id FOR UPDATE; NEW.registrado_por:=auth.uid();NEW.registrado_por_nome:=nome; IF TG_TABLE_NAME='checklists_recebimento' THEN IF TG_OP='UPDATE' THEN IF NEW.carga_entrada_id IS DISTINCT FROM OLD.carga_entrada_id THEN RAISE EXCEPTION 'O vínculo da conferência não pode mudar'; END IF;NEW.versao:=OLD.versao+1;NEW.created_at:=OLD.created_at;ELSE NEW.versao:=1;END IF;NEW.updated_at:=now(); ELSE SELECT coalesce(max(versao),0)+1 INTO NEW.versao FROM public.documentos_recebimento WHERE carga_entrada_id=NEW.carga_entrada_id AND tipo=NEW.tipo;NEW.created_at:=now();IF NEW.tipo='recibo' THEN IF NEW.dados ? 'cobrancas' THEN NEW.dados:=NEW.dados||public.calcular_descarga(NEW.dados->'cobrancas'); ELSE kg:=(NEW.dados->>'peso_kg')::numeric;tarifa:=(NEW.dados->>'tarifa')::numeric;IF kg IS NULL OR tarifa IS NULL OR kg<0 OR tarifa<0 THEN RAISE EXCEPTION 'Peso e tarifa inválidos';END IF;NEW.dados:=NEW.dados||jsonb_build_object('toneladas',kg/1000,'valor_total',round(kg/1000*tarifa,2));END IF;END IF;END IF;RETURN NEW;END $$;